#!/usr/bin/env python3
from pathlib import Path
import shutil
import sys

ROOT = Path.cwd()
PKG = Path(__file__).resolve().parent

def write(path: str, content: str, overwrite: bool = True):
    target = ROOT / path
    target.parent.mkdir(parents=True, exist_ok=True)
    if target.exists() and not overwrite:
        return
    target.write_text(content, encoding="utf-8")

def append_once(path: str, marker: str, content: str):
    target = ROOT / path
    text = target.read_text(encoding="utf-8") if target.exists() else ""
    if marker not in text:
        target.write_text(text.rstrip() + "\n\n" + content.strip() + "\n", encoding="utf-8")

def patch_block_renderer():
    path = ROOT / "apps/site/src/blocks/BlockRenderer.astro"
    text = path.read_text(encoding="utf-8")

    if "OpenHeicLanding" not in text:
        text = text.replace(
            "import AdSlot from '../components/AdSlot.astro';",
            "import AdSlot from '../components/AdSlot.astro';\nimport OpenHeicLanding from './OpenHeicLanding.astro';"
        )

    if "ctx.siteId === 'open-heic-file'" not in text:
        needle = "---\n<div class={`page-recipe page-recipe--${ctx.layoutConfig.recipe}`} data-ui-recipe={ctx.layoutConfig.recipe}>"
        replacement = "---\n{ctx.siteId === 'open-heic-file' ? (\n  <OpenHeicLanding />\n) : (\n<div class={`page-recipe page-recipe--${ctx.layoutConfig.recipe}`} data-ui-recipe={ctx.layoutConfig.recipe}>"
        if needle not in text:
            raise SystemExit("Could not patch BlockRenderer.astro: template opening not found.")
        text = text.replace(needle, replacement, 1)

        tail = "  ))}\n</div>\n"
        if tail not in text:
            raise SystemExit("Could not patch BlockRenderer.astro: template closing not found.")
        text = text.replace(tail, "  ))}\n</div>\n)}\n", 1)

    path.write_text(text, encoding="utf-8")

def patch_site_ts():
    path = ROOT / "scripts/site.ts"
    text = path.read_text(encoding="utf-8")
    if "toolId === 'open-heic-file'" not in text:
        needle = "  if (toolId === 'convert-image-to-png') {\n    return reactTool('../features/image-converter/ImageConverterIsland', { renderer: 'react', toolId, mode: '' });\n  }\n"
        insert = needle + "  if (toolId === 'open-heic-file') {\n    return reactTool('../features/open-heic-file/OpenHeicFileIsland', { renderer: 'react', toolId, mode: '' });\n  }\n"
        if needle not in text:
            raise SystemExit("Could not patch scripts/site.ts: convert-image-to-png registration not found.")
        text = text.replace(needle, insert, 1)
    path.write_text(text, encoding="utf-8")

def main():
    if not (ROOT / "pnpm-workspace.yaml").exists():
        raise SystemExit("Run this script from the seo-tool-site-factory repository root.")

    write("apps/site/src/blocks/OpenHeicLanding.astro", OPEN_HEIC_LANDING)
    write("apps/site/src/features/open-heic-file/OpenHeicFileIsland.tsx", OPEN_HEIC_ISLAND)
    append_once("apps/site/src/styles/ui-differentiation.css", "open-heic-file exact pixel mockup shell", CSS_APPEND)
    patch_block_renderer()
    patch_site_ts()

    static_dir = ROOT / "apps/site/public/heic-pixel"
    static_dir.mkdir(parents=True, exist_ok=True)
    shutil.copyfile(PKG / "assets/open-heic-mockup.png", static_dir / "open-heic-mockup.png")

    site_dir = ROOT / "sites/open-heic-file"
    (site_dir / "content/en/guides").mkdir(parents=True, exist_ok=True)
    (site_dir / "messages").mkdir(parents=True, exist_ok=True)
    (site_dir / "static").mkdir(parents=True, exist_ok=True)
    (site_dir / "snippets/ads").mkdir(parents=True, exist_ok=True)

    write("sites/open-heic-file/site.config.yaml", SITE_CONFIG_YAML, overwrite=not (site_dir / "site.config.yaml").exists())
    write("sites/open-heic-file/layout.config.yaml", LAYOUT_YAML)
    write("sites/open-heic-file/theme.config.yaml", THEME_YAML)
    write("sites/open-heic-file/tool.config.yaml", TOOL_YAML)
    write("sites/open-heic-file/integrations.config.yaml", INTEGRATIONS_YAML, overwrite=not (site_dir / "integrations.config.yaml").exists())
    write("sites/open-heic-file/brief.yaml", BRIEF_YAML, overwrite=not (site_dir / "brief.yaml").exists())
    write("sites/open-heic-file/content/en/home.mdx", HOME_MDX, overwrite=not (site_dir / "content/en/home.mdx").exists())
    write("sites/open-heic-file/content/en/faq.mdx", FAQ_MDX, overwrite=not (site_dir / "content/en/faq.mdx").exists())
    write("sites/open-heic-file/messages/en.yaml", "tool:\n  start: Open HEIC file\n", overwrite=not (site_dir / "messages/en.yaml").exists())

    print("Applied exact pixel Open HEIC UI.")
    print("Run:")
    print("  pnpm site check open-heic-file")
    print("  pnpm site dev open-heic-file")

OPEN_HEIC_LANDING = '---\nimport OpenHeicFileIsland from \'../features/open-heic-file/OpenHeicFileIsland\';\n\nconst mockupSrc = \'/heic-pixel/open-heic-mockup.png\';\n---\n\n<section class="heic-pixel-exact" aria-label="Open HEIC files instantly, privately">\n  <img\n    class="heic-pixel-exact__mockup"\n    src={mockupSrc}\n    alt="Open HEIC file online privately homepage interface"\n    width="864"\n    height="1821"\n    decoding="sync"\n    loading="eager"\n  />\n  <div class="heic-pixel-exact__semantic" aria-hidden="false">\n    <h1>Open HEIC files instantly, privately.</h1>\n    <p>Preview and convert HEIC images to JPG or PNG online. 100% private. No upload. Works on any device.</p>\n    <h2>Open and convert in 3 simple steps</h2>\n    <ol>\n      <li>Choose your HEIC file.</li>\n      <li>Preview the image locally in your browser.</li>\n      <li>Download as JPG or PNG.</li>\n    </ol>\n    <h2>Why HEIC files fail to open</h2>\n    <h2>HEIC vs JPG vs PNG</h2>\n    <h2>Fix common HEIC problems</h2>\n    <h2>Privacy by design</h2>\n    <h2>FAQ</h2>\n  </div>\n  <OpenHeicFileIsland client:load />\n</section>\n'
OPEN_HEIC_ISLAND = 'import React, { useEffect, useMemo, useRef, useState } from \'react\';\n\ntype ImageInfo = {\n  url: string;\n  name: string;\n  sizeLabel: string;\n  pixels: string;\n  jpgUrl: string | null;\n  pngUrl: string | null;\n  jpgName: string;\n  pngName: string;\n};\n\nfunction sizeLabel(size: number) {\n  if (size < 1024) return `${size} B`;\n  if (size < 1024 * 1024) return `${Math.round(size / 1024)} KB`;\n  return `${(size / 1024 / 1024).toFixed(2)} MB`;\n}\n\nfunction outputName(fileName: string, ext: \'jpg\' | \'png\') {\n  const base = fileName.replace(/\\.[^.]+$/, \'\') || \'heic-image\';\n  return `${base}.${ext}`;\n}\n\nasync function imageElementFromUrl(url: string) {\n  const image = new Image();\n  image.decoding = \'async\';\n  image.src = url;\n  await image.decode();\n  return image;\n}\n\nasync function canvasBlobFromImage(image: HTMLImageElement, mimeType: \'image/jpeg\' | \'image/png\') {\n  const canvas = document.createElement(\'canvas\');\n  canvas.width = image.naturalWidth;\n  canvas.height = image.naturalHeight;\n  const context = canvas.getContext(\'2d\');\n  if (!context) throw new Error(\'Canvas is not available in this browser.\');\n  context.drawImage(image, 0, 0);\n  return await new Promise<Blob>((resolve, reject) => {\n    canvas.toBlob((blob) => blob ? resolve(blob) : reject(new Error(\'Could not create output image.\')), mimeType, mimeType === \'image/jpeg\' ? 0.92 : undefined);\n  });\n}\n\nfunction track(eventName: string, params: Record<string, unknown>) {\n  if (typeof window !== \'undefined\') {\n    (window as any).__factoryTrack?.(eventName, params);\n  }\n}\n\nexport default function OpenHeicFileIsland() {\n  const inputRef = useRef<HTMLInputElement | null>(null);\n  const [dragging, setDragging] = useState(false);\n  const [info, setInfo] = useState<ImageInfo | null>(null);\n  const [status, setStatus] = useState<\'idle\' | \'working\' | \'ready\' | \'error\'>(\'idle\');\n  const [message, setMessage] = useState(\'Waiting for a HEIC file.\');\n\n  useEffect(() => {\n    return () => {\n      if (info?.url) URL.revokeObjectURL(info.url);\n      if (info?.jpgUrl) URL.revokeObjectURL(info.jpgUrl);\n      if (info?.pngUrl) URL.revokeObjectURL(info.pngUrl);\n    };\n  }, [info]);\n\n  const canDownload = useMemo(() => Boolean(info?.jpgUrl || info?.pngUrl), [info]);\n\n  function clear() {\n    if (info?.url) URL.revokeObjectURL(info.url);\n    if (info?.jpgUrl) URL.revokeObjectURL(info.jpgUrl);\n    if (info?.pngUrl) URL.revokeObjectURL(info.pngUrl);\n    setInfo(null);\n    setStatus(\'idle\');\n    setMessage(\'Waiting for a HEIC file.\');\n    if (inputRef.current) inputRef.current.value = \'\';\n  }\n\n  async function handleFile(file: File) {\n    if (!/\\.(heic|heif)$/i.test(file.name) && ![\'image/heic\', \'image/heif\', \'image/heic-sequence\', \'image/heif-sequence\'].includes(file.type)) {\n      setInfo(null);\n      setStatus(\'error\');\n      setMessage(\'Choose a .heic or .heif image file.\');\n      track(\'tool_error\', { toolId: \'open-heic-file\', reason: \'unsupported_extension\' });\n      return;\n    }\n\n    if (file.size > 25 * 1024 * 1024) {\n      setInfo(null);\n      setStatus(\'error\');\n      setMessage(\'File is too large. Maximum size is 25 MB.\');\n      track(\'tool_error\', { toolId: \'open-heic-file\', reason: \'file_too_large\' });\n      return;\n    }\n\n    clear();\n    setStatus(\'working\');\n    setMessage(\'Decoding in your browser...\');\n\n    const objectUrl = URL.createObjectURL(file);\n    try {\n      const image = await imageElementFromUrl(objectUrl);\n      const [jpgBlob, pngBlob] = await Promise.all([\n        canvasBlobFromImage(image, \'image/jpeg\'),\n        canvasBlobFromImage(image, \'image/png\')\n      ]);\n\n      const nextInfo: ImageInfo = {\n        url: objectUrl,\n        name: file.name,\n        sizeLabel: sizeLabel(file.size),\n        pixels: `${image.naturalWidth} × ${image.naturalHeight}`,\n        jpgUrl: URL.createObjectURL(jpgBlob),\n        pngUrl: URL.createObjectURL(pngBlob),\n        jpgName: outputName(file.name, \'jpg\'),\n        pngName: outputName(file.name, \'png\')\n      };\n      setInfo(nextInfo);\n      setStatus(\'ready\');\n      setMessage(\'Preview ready. Download JPG or PNG.\');\n      track(\'tool_complete\', { toolId: \'open-heic-file\', success: true, fileSizeBucket: file.size < 1024 * 1024 ? \'<1MB\' : file.size < 5 * 1024 * 1024 ? \'1-5MB\' : \'5MB+\' });\n    } catch {\n      URL.revokeObjectURL(objectUrl);\n      setInfo({\n        url: \'\',\n        name: file.name,\n        sizeLabel: sizeLabel(file.size),\n        pixels: \'-\',\n        jpgUrl: null,\n        pngUrl: null,\n        jpgName: outputName(file.name, \'jpg\'),\n        pngName: outputName(file.name, \'png\')\n      });\n      setStatus(\'error\');\n      setMessage(\'This browser could not decode this HEIC variant. Try Safari, iOS, or another browser with HEIC support.\');\n      track(\'tool_error\', { toolId: \'open-heic-file\', reason: \'decode_failed\' });\n    }\n  }\n\n  function onFiles(files: FileList | null) {\n    const file = files?.[0];\n    if (file) void handleFile(file);\n  }\n\n  function openPicker() {\n    inputRef.current?.click();\n  }\n\n  return (\n    <div className="heic-pixel-ui" aria-hidden="false">\n      <input\n        ref={inputRef}\n        className="heic-pixel-ui__file"\n        type="file"\n        accept=".heic,.heif,image/heic,image/heif"\n        onChange={(event) => onFiles(event.currentTarget.files)}\n      />\n\n      <button className="heic-pixel-ui__hit heic-pixel-ui__hit--nav" type="button" onClick={openPicker} aria-label="Open HEIC file" />\n      <button className="heic-pixel-ui__hit heic-pixel-ui__hit--hero" type="button" onClick={openPicker} aria-label="Open HEIC file" />\n      <button className="heic-pixel-ui__hit heic-pixel-ui__hit--sample" type="button" onClick={openPicker} aria-label="Try sample image" />\n\n      <div\n        className={`heic-pixel-ui__drop ${dragging ? \'is-dragging\' : \'\'}`}\n        onDragOver={(event) => { event.preventDefault(); setDragging(true); }}\n        onDragLeave={() => setDragging(false)}\n        onDrop={(event) => { event.preventDefault(); setDragging(false); onFiles(event.dataTransfer.files); }}\n        role="button"\n        tabIndex={0}\n        aria-label="Drag and drop your HEIC file here"\n        onClick={openPicker}\n        onKeyDown={(event) => {\n          if (event.key === \'Enter\' || event.key === \' \') {\n            event.preventDefault();\n            openPicker();\n          }\n        }}\n      />\n\n      {(status !== \'idle\' || info) && (\n        <div className={`heic-pixel-ui__live heic-pixel-ui__live--${status}`} aria-live="polite">\n          <p className="heic-pixel-ui__kicker">Status</p>\n          <strong>{status === \'ready\' ? \'HEIC file ready\' : status === \'working\' ? \'Decoding file\' : status === \'error\' ? \'Could not open file\' : \'No file selected\'}</strong>\n          <span>{message}</span>\n\n          <div className="heic-pixel-ui__stats">\n            <div>\n              <small>Format</small>\n              <b>{info ? \'HEIC\' : \'-\'}</b>\n            </div>\n            <div>\n              <small>File size</small>\n              <b>{info?.sizeLabel ?? \'-\'}</b>\n            </div>\n            <div>\n              <small>Pixels</small>\n              <b>{info?.pixels ?? \'-\'}</b>\n            </div>\n          </div>\n\n          <div className="heic-pixel-ui__actions">\n            {info?.jpgUrl ? (\n              <a href={info.jpgUrl} download={info.jpgName} onClick={() => track(\'download_action\', { toolId: \'open-heic-file\', format: \'jpg\' })}>Download JPG</a>\n            ) : <button type="button" disabled>Download JPG</button>}\n            {info?.pngUrl ? (\n              <a href={info.pngUrl} download={info.pngName} onClick={() => track(\'download_action\', { toolId: \'open-heic-file\', format: \'png\' })}>Download PNG</a>\n            ) : <button type="button" disabled>Download PNG</button>}\n            <button type="button" className="heic-pixel-ui__clear" onClick={clear}>Clear</button>\n          </div>\n\n          <p className="heic-pixel-ui__privacy">The image stays in this browser session. This tool does not upload the selected file.</p>\n        </div>\n      )}\n    </div>\n  );\n}\n'
CSS_APPEND = '\n/* open-heic-file exact pixel mockup shell */\nbody.recipe-heic-pixel-exact {\n  --factory-bg: #ffffff;\n  --factory-surface: #ffffff;\n  background: #ffffff;\n}\n\nbody.recipe-heic-pixel-exact .site-header,\nbody.recipe-heic-pixel-exact > .footer {\n  display: none !important;\n}\n\nbody.recipe-heic-pixel-exact main {\n  margin: 0;\n  padding: 0;\n  background: #ffffff;\n}\n\n.heic-pixel-exact {\n  position: relative;\n  width: 864px;\n  max-width: 100vw;\n  min-height: 1821px;\n  margin: 0 auto;\n  background: #ffffff;\n  overflow: hidden;\n  color: #080808;\n}\n\n.heic-pixel-exact__mockup {\n  display: block;\n  width: 864px;\n  max-width: 100vw;\n  height: auto;\n  margin: 0;\n  user-select: none;\n  pointer-events: none;\n}\n\n.heic-pixel-exact__semantic {\n  position: absolute;\n  width: 1px;\n  height: 1px;\n  padding: 0;\n  margin: -1px;\n  overflow: hidden;\n  clip: rect(0 0 0 0);\n  white-space: nowrap;\n  border: 0;\n}\n\n.heic-pixel-ui {\n  position: absolute;\n  inset: 0;\n  width: 864px;\n  height: 1821px;\n  transform-origin: top left;\n  font-family: Inter, ui-sans-serif, system-ui, -apple-system, BlinkMacSystemFont, "Segoe UI", sans-serif;\n  pointer-events: none;\n}\n\n.heic-pixel-ui__file {\n  position: absolute;\n  width: 1px;\n  height: 1px;\n  opacity: 0;\n  pointer-events: none;\n}\n\n.heic-pixel-ui__hit,\n.heic-pixel-ui__drop {\n  position: absolute;\n  border: 0;\n  background: transparent;\n  color: transparent;\n  cursor: pointer;\n  pointer-events: auto;\n  appearance: none;\n  padding: 0;\n}\n\n.heic-pixel-ui__hit:focus-visible,\n.heic-pixel-ui__drop:focus-visible {\n  outline: 2px solid rgba(0, 0, 0, .36);\n  outline-offset: 4px;\n  border-radius: 999px;\n}\n\n.heic-pixel-ui__hit--nav {\n  left: 704px;\n  top: 15px;\n  width: 91px;\n  height: 29px;\n  border-radius: 999px;\n}\n\n.heic-pixel-ui__hit--hero {\n  left: 92px;\n  top: 318px;\n  width: 121px;\n  height: 36px;\n  border-radius: 999px;\n}\n\n.heic-pixel-ui__hit--sample {\n  left: 222px;\n  top: 318px;\n  width: 118px;\n  height: 36px;\n  border-radius: 999px;\n}\n\n.heic-pixel-ui__drop {\n  left: 99px;\n  top: 409px;\n  width: 315px;\n  height: 242px;\n  border-radius: 18px;\n}\n\n.heic-pixel-ui__drop.is-dragging {\n  background: rgba(0, 0, 0, .035);\n  outline: 2px dashed rgba(0, 0, 0, .18);\n  outline-offset: -10px;\n}\n\n.heic-pixel-ui__live {\n  position: absolute;\n  left: 429px;\n  top: 390px;\n  width: 348px;\n  height: 268px;\n  padding: 26px 25px;\n  border-radius: 0 18px 18px 0;\n  background: rgba(255, 255, 255, .985);\n  color: #0a0a0a;\n  pointer-events: auto;\n  box-shadow: none;\n}\n\n.heic-pixel-ui__kicker {\n  margin: 0 0 6px;\n  color: #697386;\n  font-size: 11px;\n  font-weight: 800;\n  line-height: 1;\n}\n\n.heic-pixel-ui__live strong {\n  display: block;\n  margin: 0 0 6px;\n  color: #050505;\n  font-size: 17px;\n  line-height: 1.05;\n  letter-spacing: -0.03em;\n}\n\n.heic-pixel-ui__live > span {\n  display: block;\n  color: #313745;\n  font-size: 11px;\n  line-height: 1.35;\n}\n\n.heic-pixel-ui__stats {\n  display: grid;\n  grid-template-columns: repeat(3, 1fr);\n  gap: 9px;\n  margin-top: 27px;\n}\n\n.heic-pixel-ui__stats div {\n  min-height: 54px;\n  padding: 10px 11px;\n  border: 1px solid #e3e7ee;\n  border-radius: 5px;\n  background: #fff;\n}\n\n.heic-pixel-ui__stats small {\n  display: block;\n  margin-bottom: 7px;\n  color: #7b8494;\n  font-size: 10px;\n  font-weight: 700;\n  line-height: 1;\n}\n\n.heic-pixel-ui__stats b {\n  display: block;\n  color: #232937;\n  font-size: 11px;\n  line-height: 1.2;\n  overflow: hidden;\n  text-overflow: ellipsis;\n  white-space: nowrap;\n}\n\n.heic-pixel-ui__actions {\n  display: flex;\n  flex-wrap: wrap;\n  align-items: center;\n  gap: 9px;\n  margin-top: 15px;\n}\n\n.heic-pixel-ui__actions a,\n.heic-pixel-ui__actions button {\n  display: inline-flex;\n  align-items: center;\n  justify-content: center;\n  min-width: 91px;\n  height: 28px;\n  padding: 0 12px;\n  border: 0;\n  border-radius: 999px;\n  background: #0a0a0a;\n  color: #fff;\n  font-size: 10px;\n  font-weight: 800;\n  line-height: 1;\n  text-decoration: none;\n  box-shadow: none;\n  cursor: pointer;\n}\n\n.heic-pixel-ui__actions button:disabled {\n  background: #f1f3f5;\n  color: #bec3ca;\n  cursor: not-allowed;\n  opacity: 1;\n}\n\n.heic-pixel-ui__actions .heic-pixel-ui__clear {\n  min-width: 53px;\n  background: #ffffff;\n  color: #111827;\n  border: 1px solid #d7dce3;\n}\n\n.heic-pixel-ui__privacy {\n  margin: 23px 0 0;\n  color: #525b6a;\n  font-size: 10px;\n  line-height: 1.35;\n}\n\n@media (max-width: 864px) {\n  .heic-pixel-exact {\n    width: 100vw;\n    min-height: calc(1821px * (100vw / 864));\n  }\n\n  .heic-pixel-ui {\n    transform: scale(calc(100vw / 864));\n  }\n}\n'
